package batch

import (
	"context"
	"sync"
)

// Failures collects the errors of a batch. Add may be called from many goroutines.
type Failures struct {
	mu   sync.Mutex
	byID map[string]error
}

func NewFailures() *Failures {
	return &Failures{byID: make(map[string]error)}
}

func (f *Failures) Add(id string, err error) {
	f.byID[id] = err
}

func (f *Failures) Count() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return len(f.byID)
}

// Percent is the share of total calls that failed, rounded down.
func (f *Failures) Percent(total int) int {
	return f.Count() * 100 / total
}

// Process calls fn for every id, which must be distinct, with at most workers
// calls running at once, and returns the errors the calls gave.
func Process(ctx context.Context, ids []string, workers int, fn func(context.Context, string) error) *Failures {
	failures := NewFailures()
	slots := make(chan struct{}, workers)
	var wg sync.WaitGroup
	for _, id := range ids {
		slots <- struct{}{}
		wg.Add(1)
		go func(id string) {
			defer wg.Done()
			defer func() { <-slots }()
			if err := fn(ctx, id); err != nil {
				failures.Add(id, err)
			}
		}(id)
	}
	wg.Wait()
	return failures
}

