		workers = 1
	}
	failures := NewFailures()
	slots := make(chan struct{}, workers)
	var wg sync.WaitGroup
	for _, id := range ids {
		slots <- struct{}{}
		wg.Add(1)
		go func(id string) {
			defer wg.Done()
			defer func() { <-slots }()
			if err := fn(ctx, id); err != nil {
				failures.Add(id, err)
			}
		}(id)
	}
	wg.Wait()
